module ActiveSupport;class BroadcastLogger;include ActiveSupport::LoggerSilence;attr_reader:broadcasts;attr_accessor:progname;def initialize(*loggers)@broadcasts=[];@progname="Broadcast";broadcast_to(*loggers);end;def broadcast_to(*loggers)@broadcasts.concat(loggers);end;def stop_broadcasting_to(logger)@broadcasts.delete(logger);end;def local_level=(level)@broadcasts.each do |logger|logger.local_level=level if logger.respond_to?(:local_level=);end;end;def local_level;loggers=@broadcasts.select{|logger|logger.respond_to?(:local_level)};loggers.map do |logger|logger.local_level;end.first;end;LOGGER_METHODS= %w[<< log add debug info warn error fatal unknown level= sev_threshold= close formatter formatter=]
LOGGER_METHODS.each do |method|class_eval"        def #{method}(...)
          dispatch(:#{method}, ...)
        end
",__FILE__,__LINE__+1;end;def level;@broadcasts.map(&:level).min;end;def debug?;@broadcasts.any?{|logger|logger.debug?};end;def debug!;dispatch(:debug!);end;def info?;@broadcasts.any?{|logger|logger.info?};end;def info!;dispatch(:info!);end;def warn?;@broadcasts.any?{|logger|logger.warn?};end;def warn!;dispatch(:warn!);end;def error?;@broadcasts.any?{|logger|logger.error?};end;def error!;dispatch(:error!);end;def fatal?;@broadcasts.any?{|logger|logger.fatal?};end;def fatal!;dispatch(:fatal!);end;def initialize_copy(other)@broadcasts=[];@progname=other.progname.dup;broadcast_to(*other.broadcasts.map(&:dup));end;private;def dispatch(method,*args,**kwargs,&block)if block_given?;called,result=false,nil;block=proc{|*args,**kwargs|if called then result;else called=true;result=yield(*args,**kwargs);end};end;@broadcasts.map{|logger|logger.send(method,*args,**kwargs,&block)}.first;end;def method_missing(name,...)loggers=@broadcasts.select{|logger|logger.respond_to?(name)};if loggers.none?;super ;elsif loggers.one?;loggers.first.send(name,...);else loggers.map{|logger|logger.send(name,...)};end;end;def respond_to_missing?(method,include_all)@broadcasts.any?{|logger|logger.respond_to?(method,include_all)};end;end;end
